//! Cowrie circle rules. A line-for-line port of `src/engine/circle.ts`, which is the
//! reference implementation. No NEAR runtime calls live here, so the rules can be
//! unit-tested natively and replayed against vectors generated by the TypeScript engine.

use near_sdk::borsh::{BorshDeserialize, BorshSerialize};
use near_sdk::serde::{Deserialize, Serialize};

pub mod dec {
    //! u128 as a decimal string in JSON (JSON numbers cannot hold u128).
    use near_sdk::serde::{Deserialize, Deserializer, Serializer};
    pub fn serialize<S: Serializer>(v: &u128, s: S) -> Result<S::Ok, S::Error> {
        s.serialize_str(&v.to_string())
    }
    pub fn deserialize<'de, D: Deserializer<'de>>(d: D) -> Result<u128, D::Error> {
        let s = String::deserialize(d)?;
        s.parse().map_err(near_sdk::serde::de::Error::custom)
    }
}

#[derive(BorshSerialize, BorshDeserialize, Serialize, Deserialize, Clone, Debug, PartialEq)]
#[serde(crate = "near_sdk::serde")]
#[borsh(crate = "near_sdk::borsh")]
pub struct Params {
    pub members: u32,
    #[serde(with = "dec")]
    pub contribution: u128,
    pub period_secs: u64,
    pub grace_secs: u64,
    pub collateral_pct: u8,
    pub reserve_bps: u32,
    #[serde(with = "dec")]
    pub tip_cap: u128,
    pub random_order: bool,
    pub min_credentials: u32,
    pub discount_pct: u8,
}

#[derive(BorshSerialize, BorshDeserialize, Serialize, Deserialize, Clone, Copy, Debug, PartialEq)]
#[serde(crate = "near_sdk::serde", rename_all = "lowercase")]
#[borsh(crate = "near_sdk::borsh")]
pub enum Status {
    Open,
    Active,
    Completed,
    Cancelled,
}

#[derive(BorshSerialize, BorshDeserialize, Serialize, Deserialize, Clone, Debug)]
#[serde(crate = "near_sdk::serde")]
#[borsh(crate = "near_sdk::borsh")]
pub struct Member {
    pub id: String,
    pub position: i64,
    #[serde(with = "dec")]
    pub collateral: u128,
    #[serde(with = "dec")]
    pub prepaid: u128,
    pub defaults: u32,
    #[serde(with = "dec")]
    pub owed: u128,
    pub on_time: u32,
    pub received: bool,
    pub removed: bool,
}

#[derive(BorshSerialize, BorshDeserialize, Serialize, Deserialize, Clone, Debug)]
#[serde(crate = "near_sdk::serde")]
#[borsh(crate = "near_sdk::borsh")]
pub struct Round {
    pub index: u32,
    pub due_at: u64,
    /// member id -> how the contribution was covered: direct, autopay, slashed, reserve, short
    pub paid: Vec<(String, String)>,
    #[serde(with = "dec")]
    pub pot: u128,
    pub settled: bool,
    pub recipient: Option<String>,
    #[serde(with = "dec")]
    pub payout: u128,
}

impl Round {
    fn paid_of(&self, id: &str) -> bool {
        self.paid.iter().any(|(m, _)| m == id)
    }
}

#[derive(BorshSerialize, BorshDeserialize, Serialize, Deserialize, Clone, Debug)]
#[serde(crate = "near_sdk::serde")]
#[borsh(crate = "near_sdk::borsh")]
pub struct Circle {
    pub id: u64,
    pub name: String,
    pub creator: String,
    pub token: String,
    pub params: Params,
    pub status: Status,
    pub started_at: u64,
    pub members: Vec<Member>,
    pub order: Vec<String>,
    pub rounds: Vec<Round>,
    #[serde(with = "dec")]
    pub reserve: u128,
    #[serde(with = "dec")]
    pub ledger_in: u128,
    #[serde(with = "dec")]
    pub ledger_out: u128,
    pub seed: u64,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Transfer {
    pub to: String,
    pub amount: u128,
}

#[derive(Clone, Debug, PartialEq)]
pub struct CredentialMint {
    pub member: String,
    pub rounds: u32,
    pub on_time: u32,
    pub defaults: u32,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Event {
    pub kind: &'static str,
    pub data: String,
}

pub type R<T> = Result<T, String>;

fn err<T>(code: &str) -> R<T> {
    Err(code.to_string())
}

pub fn validate(p: &Params) -> R<()> {
    if p.members < 2 || p.members > 24 {
        return err("bad_members");
    }
    if p.contribution == 0 {
        return err("bad_contribution");
    }
    if ![0u8, 50, 100].contains(&p.collateral_pct) {
        return err("bad_collateral");
    }
    if p.reserve_bps > 1000 {
        return err("bad_reserve");
    }
    if p.discount_pct > 100 {
        return err("bad_discount");
    }
    if p.period_secs == 0 {
        return err("bad_period");
    }
    Ok(())
}

/// Mulberry32, bit-for-bit the generator used by the TypeScript engine.
fn rng(seed: u32) -> impl FnMut() -> f64 {
    let mut a = seed;
    move || {
        a = a.wrapping_add(0x6d2b79f5);
        let mut t = a;
        t = (t ^ (t >> 15)).wrapping_mul(t | 1);
        t ^= t.wrapping_add((t ^ (t >> 7)).wrapping_mul(t | 61));
        ((t ^ (t >> 14)) as f64) / 4294967296.0
    }
}

impl Circle {
    pub fn new(id: u64, name: String, creator: String, token: String, params: Params, seed: u64) -> R<Circle> {
        validate(&params)?;
        Ok(Circle {
            id,
            name,
            creator,
            token,
            params,
            status: Status::Open,
            started_at: 0,
            members: vec![],
            order: vec![],
            rounds: vec![],
            reserve: 0,
            ledger_in: 0,
            ledger_out: 0,
            seed,
        })
    }

    pub fn collateral_required(&self, credentials: u32) -> u128 {
        let p = &self.params;
        let full = p.contribution * (p.members as u128 - 1) * p.collateral_pct as u128 / 100;
        if credentials >= p.min_credentials && p.collateral_pct > 0 {
            full * (100 - p.discount_pct as u128) / 100
        } else {
            full
        }
    }

    fn mi(&self, id: &str) -> R<usize> {
        self.members.iter().position(|m| m.id == id).ok_or_else(|| "not_member".to_string())
    }

    fn reserve_share(&self, amount: u128) -> u128 {
        amount * self.params.reserve_bps as u128 / 10_000
    }

    pub fn join(&mut self, id: &str, credentials: u32) -> R<u128> {
        if self.status != Status::Open {
            return err("not_open");
        }
        if self.members.iter().any(|m| m.id == id) {
            return err("already_member");
        }
        if self.members.len() as u32 >= self.params.members {
            return err("full");
        }
        let col = self.collateral_required(credentials);
        self.members.push(Member {
            id: id.to_string(),
            position: -1,
            collateral: col,
            prepaid: 0,
            defaults: 0,
            owed: 0,
            on_time: 0,
            received: false,
            removed: false,
        });
        self.ledger_in += col;
        Ok(col)
    }

    /// Before start: leave and get collateral and any prepaid balance back.
    pub fn leave(&mut self, id: &str) -> R<Vec<Transfer>> {
        if self.status != Status::Open {
            return err("not_open");
        }
        let i = self.mi(id)?;
        let m = self.members.remove(i);
        let back = m.collateral + m.prepaid;
        self.ledger_out += back;
        Ok(vec![Transfer { to: m.id, amount: back }])
    }

    pub fn cancel(&mut self, by: &str) -> R<Vec<Transfer>> {
        if self.status != Status::Open {
            return err("not_open");
        }
        if by != self.creator {
            return err("creator_only");
        }
        let mut out = vec![];
        for m in self.members.iter_mut() {
            let back = m.collateral + m.prepaid;
            self.ledger_out += back;
            if back > 0 {
                out.push(Transfer { to: m.id.clone(), amount: back });
            }
            m.collateral = 0;
            m.prepaid = 0;
        }
        self.status = Status::Cancelled;
        Ok(out)
    }

    pub fn start(&mut self, now: u64, order: Option<Vec<String>>) -> R<()> {
        if self.status != Status::Open {
            return err("not_open");
        }
        if self.members.len() as u32 != self.params.members {
            return err("not_full");
        }
        let ids: Vec<String> = self.members.iter().map(|m| m.id.clone()).collect();
        let mut ord = order.unwrap_or_else(|| ids.clone());
        let mut sorted_a = ord.clone();
        sorted_a.sort();
        let mut sorted_b = ids.clone();
        sorted_b.sort();
        if sorted_a != sorted_b {
            return err("bad_order");
        }
        if self.params.random_order {
            let mut r = rng(self.seed as u32);
            ord = ids.clone();
            let mut i = ord.len() - 1;
            while i > 0 {
                let j = (r() * (i as f64 + 1.0)).floor() as usize;
                ord.swap(i, j);
                i -= 1;
            }
        }
        for (i, id) in ord.iter().enumerate() {
            let k = self.mi(id)?;
            self.members[k].position = i as i64;
        }
        self.rounds = (0..ord.len())
            .map(|i| Round {
                index: i as u32,
                due_at: now + (i as u64 + 1) * self.params.period_secs,
                paid: vec![],
                pot: 0,
                settled: false,
                recipient: None,
                payout: 0,
            })
            .collect();
        self.order = ord;
        self.status = Status::Active;
        self.started_at = now;
        Ok(())
    }

    pub fn current_round(&self) -> Option<usize> {
        self.rounds.iter().position(|r| !r.settled)
    }

    pub fn contribute(&mut self, id: &str, round: u32, amount: u128) -> R<()> {
        if self.status != Status::Active {
            return err("not_active");
        }
        let ri = match self.current_round() {
            Some(i) if self.rounds[i].index == round => i,
            _ => return err("wrong_round"),
        };
        self.mi(id)?;
        if amount != self.params.contribution {
            return err("wrong_amount");
        }
        if self.rounds[ri].paid_of(id) {
            return err("already_paid");
        }
        let rs = self.reserve_share(amount);
        self.ledger_in += amount;
        self.reserve += rs;
        let r = &mut self.rounds[ri];
        r.pot += amount - rs;
        r.paid.push((id.to_string(), "direct".to_string()));
        let k = self.mi(id)?;
        self.members[k].on_time += 1;
        Ok(())
    }

    pub fn prepay(&mut self, id: &str, amount: u128) -> R<()> {
        if self.status != Status::Active && self.status != Status::Open {
            return err("not_active");
        }
        if amount == 0 {
            return err("bad_amount");
        }
        let k = self.mi(id)?;
        self.members[k].prepaid += amount;
        self.ledger_in += amount;
        Ok(())
    }

    pub fn can_settle(&self, now: u64) -> bool {
        if self.status != Status::Active {
            return false;
        }
        match self.current_round() {
            None => false,
            Some(ri) => {
                let r = &self.rounds[ri];
                let all_paid = self.members.iter().all(|m| r.paid_of(&m.id));
                all_paid || now >= r.due_at + self.params.grace_secs
            }
        }
    }

    fn pick_recipient(&self, ri: usize) -> Option<usize> {
        let n = self.order.len();
        for k in 0..n {
            let id = &self.order[(self.rounds[ri].index as usize + k) % n];
            let mi = self.mi(id).ok()?;
            let m = &self.members[mi];
            if !m.removed && !m.received {
                return Some(mi);
            }
        }
        None
    }

    /// Returns (events, transfers). A settled round cannot settle again.
    pub fn settle(&mut self, caller: &str, now: u64) -> R<(Vec<Event>, Vec<Transfer>)> {
        if self.status != Status::Active {
            return err("not_active");
        }
        let ri = match self.current_round() {
            Some(i) => i,
            None => return err("nothing_to_settle"),
        };
        if !self.can_settle(now) {
            return err("too_early");
        }
        let c = self.params.contribution;
        let late = !self.members.iter().all(|m| self.rounds[ri].paid_of(&m.id));
        let mut events = vec![];
        let mut transfers = vec![];

        for k in 0..self.members.len() {
            let id = self.members[k].id.clone();
            if self.rounds[ri].paid_of(&id) {
                continue;
            }
            let draw = self.members[k].prepaid.min(c);
            let mut missing = c - draw;
            if draw > 0 {
                self.members[k].prepaid -= draw;
                let rs = self.reserve_share(draw);
                self.reserve += rs;
                self.rounds[ri].pot += draw - rs;
            }
            if missing == 0 {
                self.rounds[ri].paid.push((id.clone(), "autopay".into()));
                self.members[k].on_time += 1;
                events.push(Event { kind: "autopaid", data: format!("{{\"member\":\"{}\",\"round\":{},\"amount\":\"{}\"}}", id, ri, draw) });
                continue;
            }
            self.members[k].defaults += 1;
            events.push(Event { kind: "defaulted", data: format!("{{\"member\":\"{}\",\"round\":{}}}", id, ri) });
            let slash = missing.min(self.members[k].collateral);
            if slash > 0 {
                self.members[k].collateral -= slash;
                self.rounds[ri].pot += slash;
                missing -= slash;
                events.push(Event { kind: "slashed", data: format!("{{\"member\":\"{}\",\"round\":{},\"amount\":\"{}\"}}", id, ri, slash) });
            }
            let mut via = "slashed";
            if missing > 0 {
                let from_reserve = missing.min(self.reserve);
                if from_reserve > 0 {
                    self.reserve -= from_reserve;
                    self.rounds[ri].pot += from_reserve;
                    missing -= from_reserve;
                    events.push(Event { kind: "reserve_used", data: format!("{{\"round\":{},\"amount\":\"{}\"}}", ri, from_reserve) });
                    via = "reserve";
                }
            }
            if missing > 0 {
                self.members[k].owed += missing;
                via = "short";
            }
            self.rounds[ri].paid.push((id.clone(), via.into()));
            if self.members[k].defaults >= 2 && !self.members[k].received {
                self.members[k].removed = true;
            }
        }

        let mut payout = 0u128;
        let mut recipient: Option<String> = None;
        if let Some(rk) = self.pick_recipient(ri) {
            let pot = self.rounds[ri].pot;
            let offset = self.members[rk].owed.min(pot);
            self.members[rk].owed -= offset;
            self.reserve += offset;
            payout = pot - offset;
            self.members[rk].received = true;
            recipient = Some(self.members[rk].id.clone());
        } else {
            self.reserve += self.rounds[ri].pot;
        }
        self.rounds[ri].recipient = recipient.clone();
        self.rounds[ri].payout = payout;
        self.ledger_out += payout;
        self.rounds[ri].pot = 0;
        self.rounds[ri].settled = true;
        events.push(Event {
            kind: "settled",
            data: format!("{{\"round\":{},\"recipient\":{},\"payout\":\"{}\"}}", ri, recipient.as_ref().map(|r| format!("\"{}\"", r)).unwrap_or("null".into()), payout),
        });
        if let Some(r) = &recipient {
            if payout > 0 {
                transfers.push(Transfer { to: r.clone(), amount: payout });
            }
        }

        if late && self.params.tip_cap > 0 && !caller.is_empty() {
            let tip = self.params.tip_cap.min(self.reserve);
            if tip > 0 {
                self.reserve -= tip;
                self.ledger_out += tip;
                events.push(Event { kind: "tip", data: format!("{{\"to\":\"{}\",\"amount\":\"{}\"}}", caller, tip) });
                transfers.push(Transfer { to: caller.to_string(), amount: tip });
            }
        }
        Ok((events, transfers))
    }

    /// After the last round. Idempotent: returns nothing when already completed.
    pub fn finish(&mut self) -> R<(Vec<Transfer>, Vec<CredentialMint>)> {
        if self.status == Status::Completed {
            return Ok((vec![], vec![]));
        }
        if self.status != Status::Active {
            return err("not_active");
        }
        if self.rounds.iter().any(|r| !r.settled) {
            return err("rounds_pending");
        }
        let n = self.members.len() as u128;
        let share = self.reserve / n;
        let dust = self.reserve - share * n;
        let mut transfers = vec![];
        let mut mints = vec![];
        for (i, m) in self.members.iter_mut().enumerate() {
            let back = m.collateral + m.prepaid + share + if i == 0 { dust } else { 0 };
            self.ledger_out += back;
            m.collateral = 0;
            m.prepaid = 0;
            if back > 0 {
                transfers.push(Transfer { to: m.id.clone(), amount: back });
            }
            mints.push(CredentialMint {
                member: m.id.clone(),
                rounds: self.params.members,
                on_time: m.on_time,
                defaults: m.defaults,
            });
        }
        self.reserve = 0;
        self.status = Status::Completed;
        Ok((transfers, mints))
    }

    pub fn transfer_seat(&mut self, from: &str, to: &str, approved_by: &str) -> R<()> {
        if self.status != Status::Active {
            return err("not_active");
        }
        if approved_by != self.creator {
            return err("creator_only");
        }
        if self.members.iter().any(|m| m.id == to) {
            return err("already_member");
        }
        let k = self.mi(from)?;
        self.members[k].id = to.to_string();
        for o in self.order.iter_mut() {
            if o == from {
                *o = to.to_string();
            }
        }
        for r in self.rounds.iter_mut() {
            for p in r.paid.iter_mut() {
                if p.0 == from {
                    p.0 = to.to_string();
                }
            }
            if r.recipient.as_deref() == Some(from) {
                r.recipient = Some(to.to_string());
            }
        }
        Ok(())
    }

    pub fn held(&self) -> u128 {
        self.members.iter().map(|m| m.collateral + m.prepaid).sum::<u128>()
            + self.reserve
            + self.rounds.iter().map(|r| if r.settled { 0 } else { r.pot }).sum::<u128>()
    }

    pub fn conserved(&self) -> bool {
        self.ledger_in == self.ledger_out + self.held()
    }
}
